// ---------- State ----------
function defaultState(){
  return {
    lang:"react",
    colors:{ "--bg":"#050811","--red":"#61dafb","--red2":"#2a9ec4","--cyan":"#35d6df","--white":"#f4f5f7","--muted":"#b9bec9","--panel":"#0b101a","--panel2":"#101722" },
    theme:"theme-react",
    badge:"REACT",
    titleMain:"RACE",
    titleAccent:"CONDITIONS",
    subtitle:"CONCURRENCY & LOCKS",
    intro:"في المشاريع الكبيرة، الطلبات المتزامنة قد تسبب خصمًا مكررًا،\nبيع مخزون أكثر من المتاح، أو تنفيذ نفس العملية أكثر من مرة.",
    userLogo: DEFAULT_USER_LOGO,
    techLogo: TECH_LOGOS.react,
    userLogoPos:{ pos:"auto-tl", size:210, dx:0, dy:0 },
    techLogoPos:{ pos:"tr", size:230, dx:45, dy:50 },
    footer:"@egyitech",
    cards:[
      { number:"01", title:"Functional Updates", ar:"استخدم التحديث الدالي لمنع التضارب عند عدة تحديثات متتالية للحالة.",
        codeLang:"JSX", code:"const [count, setCount] = useState(0);\n\n// Always use the functional form\nsetCount(c => c + 1);", rawCode:false,
        noteTitle:"متى تستخدمه؟", noteText:"معالجة المدفوعات، تنفيذ الطلبات، Webhooks، ومنع العمليات المكررة." }
    ]
  };
}

let state = defaultState();
let history = [], future = [];
let renderTick = null;

function snapshot(){
  return JSON.stringify(state);
}
function pushHistory(){
  history.push(snapshot());
  if(history.length>60) history.shift();
  future = [];
  updateHistBtns();
}
function updateHistBtns(){
  document.getElementById('btnUndo').disabled = history.length<1;
  document.getElementById('btnRedo').disabled = future.length<1;
}
function undo(){
  if(!history.length) return;
  future.push(snapshot());
  state = JSON.parse(history.pop());
  renderAll(); updateHistBtns();
}
function redo(){
  if(!future.length) return;
  history.push(snapshot());
  state = JSON.parse(future.pop());
  renderAll(); updateHistBtns();
}

// ---------- Utils ----------
function esc(s){ return (s==null?'':String(s)).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function toast(msg){ const t=document.getElementById('toast'); t.textContent=msg; t.classList.add('show'); clearTimeout(t._t); t._t=setTimeout(()=>t.classList.remove('show'),2200); }

// ---------- Code highlighter ----------
const KW = {
  php:['use','function','return','if','else','elseif','foreach','for','while','class','public','private','protected','static','new','try','catch','throw','namespace','as','null','true','false','echo','print','isset','unset','require','require_once','include','extends','implements','interface','abstract','final','const','global','array','int','string','bool','float','void','self','parent','this'],
  js:['const','let','var','function','return','if','else','for','while','class','new','try','catch','throw','async','await','import','export','from','default','null','true','false','undefined','typeof','instanceof','this','yield','switch','case','break','continue','do','in','of','delete','void','static','extends','super'],
  jsx:['const','let','var','function','return','if','else','for','while','class','new','try','catch','throw','async','await','import','export','from','default','null','true','false','undefined','typeof','this','yield','switch','case','break','continue','useState','useEffect','useRef','useMemo','useCallback','useContext','do','in','of','extends','super'],
  vue:['const','let','ref','reactive','computed','watch','watchEffect','function','return','if','else','import','export','from','default','null','true','false','this','async','await','defineProps','defineEmits','defineExpose','template','script','setup','onMounted','onUnmounted','do','for','while','class'],
  css:[], html:[], bash:['const','let','function','return','if','then','fi','for','do','done','echo','export','sudo','npm','php','artisan','composer'],
};
function highlightCode(code, lang){
  if(code==null) return '';
  // raw HTML mode
  if(typeof code==='string' && /<span\s/i.test(code)) return code;
  const src = String(code);
  const K = KW[lang] || KW.js;
  const re = /(\/\/[^\n]*|#[^\n]*|\/\*[\s\S]*?\*\/)|("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`)|(\$\w+)|(\b\d+(?:\.\d+)?\b)|([A-Za-z_$][\w$]*)|(\s+)|([\s\S])/g;
  let out='', m;
  while((m=re.exec(src))){
    const t=m[0];
    if(m[1]) out+='<span class="comment">'+esc(t)+'</span>';
    else if(m[2]) out+='<span class="str">'+esc(t)+'</span>';
    else if(m[3]) out+='<span class="var">'+esc(t)+'</span>';
    else if(m[4]) out+='<span class="cyan">'+esc(t)+'</span>';
    else if(m[5]){
      const nxt=src[re.lastIndex];
      if(K.includes(t)) out+='<span class="k">'+esc(t)+'</span>';
      else if(nxt==='(') out+='<span class="fn">'+esc(t)+'</span>';
      else if(/^[A-Z]/.test(t)) out+='<span class="red">'+esc(t)+'</span>';
      else out+='<span class="var">'+esc(t)+'</span>';
    }
    else out+=esc(t);
  }
  return out;
}

// ---------- Render poster ----------
function renderPoster(){
  const s = state;
  const cssVars = COLOR_VARS.map(v=>`${v.k}:${s.colors[v.k]||''}`).join(';');
  const cards = s.cards.map((c,i)=>`
    <div class="card" data-i="${i}">
      <div class="number">${esc(c.number)}</div>
      <h2>${esc(c.title)}</h2>
      <p class="ar">${esc(c.ar).replace(/\n/g,'<br>')}</p>
      ${c.code!==undefined && c.code!==null && c.code!=='' ? `
      <div class="code">
        <div class="code-head">
          <div class="dots"><span class="dot"></span><span class="dot"></span><span class="dot"></span></div>
          <span>${esc(c.codeLang||'CODE')}</span>
        </div>
        <pre>${c.rawCode ? c.code : highlightCode(c.code, (c.codeLang||'').toLowerCase())}</pre>
      </div>`:''}
      ${(c.noteTitle||c.noteText) ? `
      <div class="note ar">
        ${c.noteTitle?`<strong>${esc(c.noteTitle)}</strong><br>`:''}
        ${esc(c.noteText||'').replace(/\n/g,'<br>')}
      </div>`:''}
    </div>`).join('');

  const footerSVG = `
    <svg viewBox="0 0 24 24" aria-label="Instagram"><path d="M12 2.163c3.204 0 3.584.012 4.85.07 3.252.148 4.771 1.691 4.919 4.919.058 1.265.069 1.645.069 4.849 0 3.205-.012 3.584-.069 4.849-.149 3.225-1.664 4.771-4.919 4.919-1.266.058-1.644.07-4.85.07-3.204 0-3.584-.012-4.849-.07-3.26-.149-4.771-1.699-4.919-4.92-.058-1.265-.07-1.644-.07-4.849 0-3.204.013-3.583.07-4.849.149-3.227 1.664-4.771 4.919-4.919 1.266-.057 1.645-.069 4.849-.069zm0-2.163c-3.259 0-3.667.014-4.947.072-4.358.2-6.78 2.618-6.98 6.98-.059 1.281-.073 1.689-.073 4.948 0 3.259.014 3.668.072 4.948.2 4.358 2.618 6.78 6.98 6.98 1.281.058 1.689.072 4.948.072 3.259 0 3.668-.014 4.948-.072 4.354-.2 6.782-2.618 6.979-6.98.059-1.28.073-1.689.073-4.948 0-3.259-.014-3.667-.072-4.947-.196-4.354-2.617-6.78-6.979-6.98-1.281-.059-1.69-.073-4.949-.073zm0 5.838c-3.403 0-6.162 2.759-6.162 6.162s2.759 6.163 6.162 6.163 6.162-2.759 6.162-6.163c0-3.403-2.759-6.162-6.162-6.162zm0 10.162c-2.209 0-4-1.79-4-4 0-2.209 1.791-4 4-4s4 1.791 4 4c0 2.21-1.791 4-4 4zm6.406-11.845c-.796 0-1.441.645-1.441 1.44s.645 1.44 1.441 1.44c.795 0 1.439-.645 1.439-1.44s-.644-1.44-1.439-1.44z"/></svg>
    <svg viewBox="0 0 24 24" aria-label="Facebook"><path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z"/></svg>
    <svg class="globe" viewBox="0 0 24 24" aria-label="Website"><circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15.3 15.3 0 0 1 0 20 15.3 15.3 0 0 1 0-20z"/></svg>`;

  // Logo positioning
  const ul = s.userLogoPos || {pos:"auto-tl",size:210,dx:0,dy:0};
  const tl = s.techLogoPos || {pos:"tr",size:230,dx:45,dy:50};
  // Reset all anchor props then set only the ones for the chosen corner,
  // so CSS defaults (e.g. .tech-logo{right:45px;top:50px}) don't conflict.
  function cornerStyle(p){
    const reset="left:auto;right:auto;top:auto;bottom:auto;";
    if(p.pos==="tl") return `position:absolute;${reset}left:${p.dx}px;top:${p.dy}px;`;
    if(p.pos==="tr") return `position:absolute;${reset}right:${p.dx}px;top:${p.dy}px;`;
    if(p.pos==="bl") return `position:absolute;${reset}left:${p.dx}px;bottom:${p.dy}px;`;
    if(p.pos==="br") return `position:absolute;${reset}right:${p.dx}px;bottom:${p.dy}px;`;
    return "";
  }
  // user logo: "auto-tl" keeps original in-flow .brand; otherwise absolute
  const userWrapStyle = ul.pos==="auto-tl"
    ? `width:${ul.size}px;`
    : cornerStyle(ul)+`width:${ul.size}px;`;
  const userWrapClass = ul.pos==="auto-tl" ? "brand" : "logo-abs";
  const techStyle = cornerStyle(tl)+`width:${tl.size}px;height:${Math.round(tl.size*190/230)}px;`;

  const html = `
  <section class="poster ${esc(s.theme)}" dir="ltr" style="${cssVars}">
    <div class="curve"></div>
    <div class="${userWrapClass}" style="${userWrapStyle}"><img class="user-logo" src="${esc(s.userLogo)}" alt="user logo"></div>
    <img class="tech-logo" src="${esc(s.techLogo)}" alt="tech logo" crossorigin="anonymous" referrerpolicy="no-referrer" style="${techStyle}">
    <div class="title">
      <div class="badge">${esc(s.badge)}</div>
      <div class="tips">${esc(s.titleMain)} <span>${esc(s.titleAccent)}</span></div>
      <div class="subtitle">${esc(s.subtitle)}</div>
    </div>
    <div class="intro ar">${esc(s.intro).replace(/\n/g,'<br>')}</div>
    ${cards}
    <div class="footer">${footerSVG}${esc(s.footer)}</div>
  </section>`;
  document.getElementById('stage').innerHTML = html;
}

// ---------- Sidebar render ----------
function sidebarSection(id, title, icon, bodyHTML, open){
  return `<div class="sec ${open?'open':''}" id="sec-${id}">
    <div class="sec-h" onclick="toggleSec('${id}')">
      ${icon}<span>${title}</span><span class="arr">▶</span>
    </div>
    <div class="sec-b">${bodyHTML}</div>
  </div>`;
}
function toggleSec(id){
  document.getElementById('sec-'+id).classList.toggle('open');
}
window.toggleSec = toggleSec;

function renderSidebar(){
  const s = state;
  const icons = {
    lang:'<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 6h16M4 12h16M4 18h10"/></svg>',
    color:'<svg class="ic" viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="12" r="4"/></svg>',
    theme:'<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M9 21V9"/></svg>',
    title:'<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 5h14M5 12h14M5 19h6"/></svg>',
    card:'<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="6" rx="2"/><rect x="3" y="14" width="18" height="6" rx="2"/></svg>',
    logo:'<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="9" cy="9" r="2"/><path d="M21 15l-5-5L5 21"/></svg>',
    foot:'<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 17l4-4 4 4 8-8"/></svg>',
  };

  // Language / preset
  let presetHTML = '<div class="presets">';
  Object.keys(PRESETS).forEach(k=>{
    const p=PRESETS[k];
    presetHTML += `<div class="preset" onclick="applyPreset('${k}')"><span class="sw" style="background:${p.red}"></span>${p.label}</div>`;
  });
  presetHTML += '</div>';

  // Colors
  let colorHTML = '<div class="color-grid">';
  COLOR_VARS.forEach(v=>{
    const val = s.colors[v.k] || '#000000';
    colorHTML += `<div class="color-cell">
      <input type="color" value="${val}" data-cv="${v.k}" oninput="setColor('${v.k}',this.value)">
      <span class="lbl">${v.nm}</span>
      <input class="hex" type="text" value="${val}" data-cvh="${v.k}" oninput="setColor('${v.k}',this.value)">
    </div>`;
  });
  colorHTML += '</div>';

  // Theme
  let themeHTML = '<div class="themes">';
  THEMES.forEach(t=>{
    themeHTML += `<div class="theme-opt ${s.theme===t.id?'sel':''}" onclick="setTheme('${t.id}')">
      <div class="nm">${t.nm}</div>
    </div>`;
  });
  themeHTML += '</div>';

  // Title fields
  const titleHTML = `
    <div class="fld"><label>الشارة (Badge)</label><input type="text" value="${esc(s.badge)}" oninput="setField('badge',this.value)"></div>
    <div class="fld"><label>العنوان الرئيسي</label><input type="text" value="${esc(s.titleMain)}" oninput="setField('titleMain',this.value)"></div>
    <div class="fld"><label>الكلمة المميزة (لون مختلف)</label><input type="text" value="${esc(s.titleAccent)}" oninput="setField('titleAccent',this.value)"></div>
    <div class="fld"><label>العنوان الفرعي</label><input type="text" value="${esc(s.subtitle)}" oninput="setField('subtitle',this.value)"></div>
    <div class="fld"><label>المقدمة (عربي RTL)</label><textarea oninput="setField('intro',this.value)">${esc(s.intro)}</textarea></div>`;

  // Cards
  let cardsHTML = '';
  s.cards.forEach((c,i)=>{
    cardsHTML += `<div class="card-item" id="ci-${i}">
      <div class="ci-h">
        <div class="num">${esc(c.number||'?')}</div>
        <div class="tt">${esc(c.title||'بدون عنوان')}</div>
        <div class="mv">
          <button class="iconbtn" onclick="moveCard(${i},-1)" title="أعلى">▲</button>
          <button class="iconbtn" onclick="moveCard(${i},1)" title="أسفل">▼</button>
          <button class="iconbtn" onclick="toggleCard(${i})" title="طي">▾</button>
          <button class="iconbtn del" onclick="delCard(${i})" title="حذف">✕</button>
        </div>
      </div>
      <div class="ci-body">
        <div class="row">
          <div class="fld"><label>الرقم</label><input type="text" value="${esc(c.number)}" oninput="setCard(${i},'number',this.value)"></div>
          <div class="fld"><label>عنوان البطاقة (EN)</label><input type="text" value="${esc(c.title)}" oninput="setCard(${i},'title',this.value)"></div>
        </div>
        <div class="fld"><label>النص العربي (RTL)</label><textarea oninput="setCard(${i},'ar',this.value)">${esc(c.ar)}</textarea></div>
        <div class="row">
          <div class="fld"><label>لغة الكود</label><input type="text" value="${esc(c.codeLang)}" oninput="setCard(${i},'codeLang',this.value)" placeholder="PHP / JSX / Vue / JS"></div>
          <div class="fld" style="flex:0 0 130px;align-self:flex-end">
            <label class="chk"><input type="checkbox" ${c.rawCode?'checked':''} onchange="setCard(${i},'rawCode',this.checked)"> كود HTML خام</label>
          </div>
        </div>
        <div class="fld"><label>الكود ${c.rawCode?'(HTML خام مع spans)':'(تلوين تلقائي)'}</label><textarea style="min-height:120px;font-family:'Courier New',monospace;direction:ltr;text-align:left" oninput="setCard(${i},'code',this.value)">${esc(c.code)}</textarea></div>
        <div class="fld"><label>عنوان الملاحظة</label><input type="text" value="${esc(c.noteTitle)}" oninput="setCard(${i},'noteTitle',this.value)"></div>
        <div class="fld"><label>نص الملاحظة (عربي)</label><textarea oninput="setCard(${i},'noteText',this.value)">${esc(c.noteText)}</textarea></div>
      </div>
    </div>`;
  });
  cardsHTML += `<button class="addbtn" onclick="addCard()">+ إضافة بطاقة</button>`;

  // Logo position controls block
  function posControls(key, isUser){
    const p = isUser ? (s.userLogoPos||{pos:"auto-tl",size:210,dx:0,dy:0})
                     : (s.techLogoPos||{pos:"tr",size:230,dx:45,dy:50});
    const opts = isUser
      ? [['auto-tl','أعلى يسار (تلقائي)'],['tl','أعلى يسار (مطلق)'],['tr','أعلى يمين'],['bl','أسفل يسار'],['br','أسفل يمين']]
      : [['tr','أعلى يمين (تلقائي)'],['tl','أعلى يسار'],['bl','أسفل يسار'],['br','أسفل يمين']];
    const optHTML = opts.map(o=>`<option value="${o[0]}" ${p.pos===o[0]?'selected':''}>${o[1]}</option>`).join('');
    return `
      <div class="fld"><label>الموضع</label>
        <select onchange="setLogoPos('${key}','pos',this.value)">${optHTML}</select>
      </div>
      <div class="fld"><label>الحجم (px) — <b>${p.size}</b></label>
        <input type="range" min="60" max="400" value="${p.size}" oninput="setLogoPos('${key}','size',+this.value);this.previousElementSibling.querySelector('b').textContent=this.value">
      </div>
      <div class="row">
        <div class="fld"><label>إزاحة X (px)</label><input type="number" value="${p.dx}" oninput="setLogoPos('${key}','dx',+this.value||0)"></div>
        <div class="fld"><label>إزاحة Y (px)</label><input type="number" value="${p.dy}" oninput="setLogoPos('${key}','dy',+this.value||0)"></div>
      </div>
      <div class="fld"><button class="addbtn" onclick="resetLogoPos('${key}')">إعادة للموضع الافتراضي</button></div>`;
  }

  // Logos
  const logoHTML = `
    <div class="fld"><label>شعار المستخدم</label>
      <div class="drop" id="dropUser" onclick="pickFile('userLogo')">
        ${s.userLogo ? `<img class="pv" src="${esc(s.userLogo)}">`:''}
        <div class="pl">اسحب صورة هنا أو انقر للرفع</div>
        ${s.userLogo?`<button class="rm" onclick="event.stopPropagation();clearLogo('userLogo')">إزالة</button>`:''}
      </div>
    </div>
    ${posControls('userLogoPos',true)}
    <div class="fld" style="margin-top:18px;border-top:1px solid var(--ui-line);padding-top:14px"><label>شعار التقنية</label>
      <div class="drop" id="dropTech" onclick="pickFile('techLogo')">
        ${s.techLogo ? `<img class="pv" src="${esc(s.techLogo)}">`:''}
        <div class="pl">اسحب صورة هنا أو انقر للرفع</div>
        ${s.techLogo?`<button class="rm" onclick="event.stopPropagation();clearLogo('techLogo')">إزالة</button>`:''}
      </div>
    </div>
    ${posControls('techLogoPos',false)}
    <div class="fld"><label>أو رابط شعار التقنية (URL)</label><input type="text" value="${esc(s.techLogo)}" oninput="setField('techLogo',this.value)" placeholder="https://..."></div>`;

  const footHTML = `<div class="fld"><label>نص الفوتر (المعرّف)</label><input type="text" value="${esc(s.footer)}" oninput="setField('footer',this.value)"></div>`;

  const sb = document.getElementById('sidebar');
  sb.innerHTML =
    sidebarSection('lang','اللغة / القالب',icons.lang,presetHTML,true) +
    sidebarSection('color','الألوان',icons.color,colorHTML,false) +
    sidebarSection('theme','ثيم الخلفية',icons.theme,themeHTML,false) +
    sidebarSection('title','العنوان والمقدمة',icons.title,titleHTML,true) +
    sidebarSection('card','البطاقات',icons.card,cardsHTML,true) +
    sidebarSection('logo','الشعارات',icons.logo,logoHTML,false) +
    sidebarSection('foot','الفوتر',icons.foot,footHTML,false);

  // wire dropzones
  ['dropUser','dropTech'].forEach(id=>{
    const el=document.getElementById(id); if(!el) return;
    const key = id==='dropUser'?'userLogo':'techLogo';
    el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('over')});
    el.addEventListener('dragleave',()=>el.classList.remove('over'));
    el.addEventListener('drop',e=>{
      e.preventDefault();el.classList.remove('over');
      const f=e.dataTransfer.files[0]; if(f) readImage(f,key);
    });
  });
}

// ---------- Mutations ----------
function scheduleRender(){ clearTimeout(renderTick); renderTick=setTimeout(renderPoster,30); }

function applyPreset(key){
  const p = PRESETS[key];
  pushHistory();
  state.lang = key;
  state.colors['--red'] = p.red;
  state.colors['--red2'] = p.red2;
  state.theme = p.theme;
  state.badge = p.badge;
  state.techLogo = TECH_LOGOS[p.tech];
  renderAll();
  toast('تم تطبيق قالب '+p.label);
}
function setColor(k,v){
  if(!/^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(v)) return;
  state.colors[k]=v;
  // sync both inputs
  document.querySelectorAll(`[data-cv="${k}"]`).forEach(el=>{if(el.value.toLowerCase()!==v.toLowerCase())el.value=v});
  document.querySelectorAll(`[data-cvh="${k}"]`).forEach(el=>{if(el.value.toLowerCase()!==v.toLowerCase())el.value=v});
  scheduleRender();
}
function setTheme(t){ pushHistory(); state.theme=t; renderAll(); }
function setField(k,v){ state[k]=v; scheduleRender(); }
function setCard(i,k,v){ state.cards[i][k]=v; scheduleRender(); if(k==='number'||k==='title') refreshCardHeader(i); }
function refreshCardHeader(i){ const ci=document.getElementById('ci-'+i); if(!ci)return; ci.querySelector('.num').textContent=state.cards[i].number||'?'; ci.querySelector('.tt').textContent=state.cards[i].title||'بدون عنوان'; }
function addCard(){ pushHistory(); state.cards.push({number:String(state.cards.length+1).padStart(2,'0'),title:'New Card',ar:'',codeLang:'JSX',code:'',rawCode:false,noteTitle:'',noteText:''}); renderAll(); }
function delCard(i){ pushHistory(); state.cards.splice(i,1); renderAll(); }
function moveCard(i,dir){ const j=i+dir; if(j<0||j>=state.cards.length)return; pushHistory(); const a=state.cards; [a[i],a[j]]=[a[j],a[i]]; renderAll(); }
function toggleCard(i){ const ci=document.getElementById('ci-'+i); if(ci) ci.classList.toggle('collapsed'); }
function clearLogo(k){ pushHistory(); state[k]=''; renderAll(); }
function setLogoPos(key, field, val){
  if(!state[key]) state[key]={pos:field==='pos'?val:'auto-tl',size:210,dx:0,dy:0};
  state[key][field]=val;
  scheduleRender();
}
function resetLogoPos(key){
  pushHistory();
  state[key] = key==='userLogoPos'
    ? {pos:"auto-tl",size:210,dx:0,dy:0}
    : {pos:"tr",size:230,dx:45,dy:50};
  renderAll();
  toast('تم إعادة الموضع الافتراضي');
}

function pickFile(key){ const inp=document.createElement('input'); inp.type='file'; inp.accept='image/*'; inp.onchange=()=>{ if(inp.files[0]) readImage(inp.files[0],key); }; inp.click(); }
function readImage(file,key){
  const r=new FileReader();
  r.onload=()=>{ pushHistory(); state[key]=r.result; renderAll(); toast('تم رفع الصورة'); };
  r.readAsDataURL(file);
}

// ---------- Save / Load ----------
function saveJSON(){
  const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=`poster-${(state.badge||'ai-topics').toLowerCase().replace(/\s+/g,'-')}.json`;
  a.click(); URL.revokeObjectURL(a.href);
  toast('تم حفظ المشروع');
}
function loadJSON(file){
  const r=new FileReader();
  r.onload=()=>{ try{
    pushHistory();
    const d=defaultState(), loaded=JSON.parse(r.result);
    state=Object.assign(d,loaded);
    // deep-merge logo positions so old projects keep defaults for missing fields
    state.userLogoPos=Object.assign({pos:"auto-tl",size:210,dx:0,dy:0}, loaded.userLogoPos||{});
    state.techLogoPos=Object.assign({pos:"tr",size:230,dx:45,dy:50}, loaded.techLogoPos||{});
    future=[]; renderAll(); toast('تم تحميل المشروع');
  }catch(e){ toast('ملف غير صالح'); } };
  r.readAsText(file);
}
function newProject(){ if(confirm('بدء مشروع جديد؟ سيتم فقدان التعديلات غير المحفوظة.')){ pushHistory(); state=defaultState(); history=[]; future=[]; renderAll(); updateHistBtns(); toast('مشروع جديد'); } }

// ---------- Export PNG ----------
async function exportPNG(){
  const poster=document.querySelector('.poster');
  if(!poster){ toast('لا يوجد بوستر'); return; }
  toast('جاري التصدير...');
  try{
    await document.fonts.ready;
    // wait for images
    const imgs=poster.querySelectorAll('img');
    await Promise.all(Array.from(imgs).map(img=> img.complete?Promise.resolve():new Promise(res=>{img.onload=img.onerror=res;})));
    const canvas=await html2canvas(poster,{backgroundColor:null,scale:3,useCORS:true,allowTaint:true,logging:false,windowWidth:poster.scrollWidth,windowHeight:poster.scrollHeight});
    canvas.toBlob(blob=>{
      const a=document.createElement('a');
      a.href=URL.createObjectURL(blob);
      a.download=`poster-${(state.badge||'ai-topics').toLowerCase().replace(/\s+/g,'-')}.png`;
      a.click(); URL.revokeObjectURL(a.href);
      toast('تم تصدير PNG ✓');
    },'image/png');
  }catch(e){ console.error(e); toast('فشل التصدير: '+e.message); }
}

// ---------- Render orchestration ----------
function renderAll(){ renderSidebar(); renderPoster(); }

// ---------- Init ----------
function init(){
  renderAll();
  updateHistBtns();

  document.getElementById('btnUndo').onclick=undo;
  document.getElementById('btnRedo').onclick=redo;
  document.getElementById('btnNew').onclick=newProject;
  document.getElementById('btnSave').onclick=saveJSON;
  document.getElementById('btnLoad').onclick=()=>document.getElementById('fileLoad').click();
  document.getElementById('fileLoad').onchange=e=>{ if(e.target.files[0]) loadJSON(e.target.files[0]); e.target.value=''; };
  document.getElementById('btnExport').onclick=exportPNG;

  const zoom=document.getElementById('zoom'), zv=document.getElementById('zoomVal'), stage=document.getElementById('stage');
  function applyZoom(){ const z=zoom.value; zv.textContent=z+'%'; stage.style.transform=`scale(${z/100})`; stage.style.transformOrigin='top center'; }
  zoom.oninput=applyZoom; applyZoom();

  document.addEventListener('keydown',e=>{
    if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){ e.preventDefault(); if(e.shiftKey) redo(); else undo(); }
    if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){ e.preventDefault(); redo(); }
    if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){ e.preventDefault(); saveJSON(); }
  });
}
init();
